       CASE WHEN v.kind = 'Budget' THEN v.day || '|Budget' ELSE v.day END,
       -(((v.day)::date - DATE '1970-01-01')::int),
       jsonb_build_object('startingDate', v.day, 'currencyRatio', v.ratio, 'rateType', v.kind, 'rateSource', v.source, 'rateBase', 'EUR')
  FROM (VALUES
    ('USD', '2025-01-01', 1.0321, 'Budget', 'budget-plan'),
    ('USD', '2026-01-01', 1.1721, 'Budget', 'budget-plan'),
    ('GBP', '2025-01-01', 0.83118, 'Budget', 'budget-plan'),
